def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents and their yesterday bids
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            prev = o.get('previous_trace', {}) or {}
            alive_opps.append((oid, o, prev))

    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    yesterday_bids = []
    for _, o, prev in alive_opps:
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    second_prev_bid = 0.0
    if len(yesterday_bids) >= 2:
        sorted_b = sorted(yesterday_bids)
        second_prev_bid = sorted_b[-2]

    # Supply pressure: if supply is tight relative to WATER_REQ, we must bid more.
    # Expected number of winners is roughly supply/WATER_REQ; higher means less competition.
    # Use a smooth heuristic.
    competition = 1.0
    if supply <= WATER_REQ:
        competition = 1.35
    elif supply <= 1.4 * WATER_REQ:
        competition = 1.2
    elif supply >= 1.9 * WATER_REQ:
        competition = 0.9

    # Determine baseline bid target based on yesterday's top spenders.
    # If someone was bidding near/above 0.85*DAILY_SALARY, they likely try to lock water.
    lock_threshold = 0.85 * DAILY_SALARY

    # Preserve budget when hp is healthy; spend more when hp is low or no_water_days is high.
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Risk adjustment
    if hp <= 1.5:
        risk_mult = 1.35
    elif hp <= 3.0:
        risk_mult = 1.2
    else:
        risk_mult = 1.0

    if no_water_days >= 2:
        risk_mult *= 1.15

    # If top bidder likely strong, bid slightly above the second-highest yesterday to beat them.
    if highest_prev_bid >= lock_threshold:
        target = second_prev_bid + 2.0
    else:
        # Otherwise bid around the mid of yesterday top and a moderate level.
        target = max(DAILY_SALARY * 0.5, highest_prev_bid * 0.9)

    target *= competition * risk_mult

    # Cap and floor to avoid extreme spending.
    # If supply is medium (15-25), we don't need to go near max unless hp is critical.
    min_bid = 0.25 * DAILY_SALARY
    max_bid = DAILY_SALARY * (1.05 if hp <= 3.0 else 0.85)

    bid = float(max(min_bid, min(target, max_bid, budget)))

    # Early days: slightly more aggressive; late days: conserve.
    if day <= 3:
        bid *= 1.05
    elif day >= 8:
        bid *= 0.9

    bid = float(max(0.0, min(bid, budget)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    desperate_count = 0
    fixed_david_like = []

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))
            prev = opp.get('previous_trace', {}) or {}
            pbid = prev.get('bid')
            if pbid is not None:
                prev_bids.append(float(pbid))
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            if pbid is not None and abs(float(pbid) - 76.0) < 0.01:
                fixed_david_like.append(float(pbid))

    if not alive:
        return float(min(budget, 18.0))

    competitors = len(alive) + 1
    units = supply / float(WATER_REQ)
    scarcity = units < competitors
    very_tight = units < max(1.5, competitors - 1)

    highest_prev = max(prev_bids) if prev_bids else 83.0
    low_prev = min(prev_bids) if prev_bids else 76.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2
    if day >= 8:
        urgency += 1

    if urgency >= 5:
        bid = max(86.0, highest_prev + 2.0)
    elif urgency >= 3:
        if scarcity:
            bid = max(78.0, min(88.0, low_prev + 2.5))
        else:
            bid = 58.0
    else:
        if very_tight:
            if fixed_david_like:
                bid = 77.5
            else:
                bid = max(74.0, min(79.0, low_prev + 1.5))
        elif scarcity:
            if desperate_count >= 2 and hp >= 6:
                bid = 24.0
            else:
                bid = 52.0
        else:
            bid = 18.0

    if highest_prev >= 120.0 and urgency <= 2:
        bid = min(bid, 20.0)
    elif highest_prev >= 90.0 and urgency <= 1 and not very_tight:
        bid = min(bid, 26.0)

    remaining_days = max(1, 10 - day)
    reserve = remaining_days * 20.0
    cap = budget
    if urgency <= 1:
        cap = min(cap, max(15.0, budget - reserve))
    elif urgency == 2:
        cap = min(cap, max(30.0, budget - reserve * 0.5))

    if cap < 0:
        cap = 0.0

    final_bid = min(budget, cap if cap > 0 else budget, bid)

    if urgency >= 4:
        final_bid = min(budget, max(final_bid, 84.0))
    elif urgency >= 3:
        final_bid = min(budget, max(final_bid, 72.0 if scarcity else 58.0))

    if final_bid < 0:
        final_bid = 0.0
    return float(final_bid)
